-- 推日動作（圖片一）
INSERT IGNORE INTO exercises (name, target_muscle, hypertrophy_reps_min, hypertrophy_reps_max, fatloss_reps_min, fatloss_reps_max, hypertrophy_sets_min, hypertrophy_sets_max, fatloss_sets_min, fatloss_sets_max, hypertrophy_load_min_pct, hypertrophy_load_max_pct, fatloss_load_min_pct, fatloss_load_max_pct, instruction_full, instruction_short, difficulty, user_level, notes, video_url, instruction_cues) VALUES
('平板臥推', '中胸', 6, 8, 8, 12, 3, 5, 3, 4, 80, 100, 60, 80, '躺在平板凳上，雙腳平放地面，握住槓鈴，緩慢下降至胸部，然後推起至起始位置', '平板臥推是練胸的基礎動作', 2, '有基礎', '注意肩胛骨穩定，避免肩部前移', '', '保持核心穩定，控制下降速度'),

('坐姿肩上推舉', '肩膀前束', 8, 12, 10, 15, 3, 5, 3, 4, 60, 75, 50, 65, '坐在凳子上，背部挺直，握住啞鈴或槓鈴，從肩膀高度推舉至頭頂上方', '坐姿推舉是練肩膀前束的主要動作', 2, '有基礎', '保持背部挺直，避免腰部過度彎曲', '', '控制下降速度，感受肩膀前束的收縮'),

('上斜啞鈴推舉', '上胸', 8, 12, 10, 15, 3, 4, 3, 4, 50, 65, 40, 55, '調整凳子至30-45度角，握住啞鈴，從胸部高度推舉至頭頂上方', '上斜推舉主要訓練上胸肌', 2, '有基礎', '注意啞鈴軌跡，避免過度外展', '', '感受上胸的收縮，控制重量'),

('伏地挺身', '中胸', 8, 15, 10, 20, 2, 4, 3, 5, 0, 0, 0, 0, '俯臥撐姿勢，雙手略寬於肩膀，身體保持一直線，下降至胸部接近地面，然後推起', '伏地挺身是練胸的自重動作', 1, '新手', '保持身體一直線，核心收緊', '', '控制下降和上升速度，感受胸部收縮'),

('啞鈴側平舉', '肩膀中束', 10, 15, 12, 20, 2, 4, 3, 4, 15, 25, 10, 20, '站立，雙手握住啞鈴，從身體兩側平舉至肩膀高度，然後緩慢下降', '側平舉主要訓練肩膀中束', 1, '新手', '避免擺動，控制重量', '', '感受肩膀中束的收縮，避免借力'),

('纜繩三頭下壓', '三頭肌', 10, 15, 12, 20, 2, 4, 3, 4, 30, 45, 25, 40, '站在纜繩機前，握住把手，肘部固定，從彎曲位置下壓至手臂伸直', '纜繩下壓是練三頭肌的經典動作', 1, '新手', '保持肘部固定，避免擺動', '', '感受三頭肌的收縮，控制重量');

-- 拉日動作（圖片二）
INSERT IGNORE INTO exercises (name, target_muscle, hypertrophy_reps_min, hypertrophy_reps_max, fatloss_reps_min, fatloss_reps_max, hypertrophy_sets_min, hypertrophy_sets_max, fatloss_sets_min, fatloss_sets_max, hypertrophy_load_min_pct, hypertrophy_load_max_pct, fatloss_load_min_pct, fatloss_load_max_pct, instruction_full, instruction_short, difficulty, user_level, notes, video_url, instruction_cues) VALUES
('輔助引體向上', '上背', 6, 10, 8, 15, 3, 5, 3, 4, 0, 0, 0, 0, '使用輔助引體向上機，雙手握住把手，從懸掛位置拉至下巴超過橫桿', '輔助引體向上是練上背的經典動作', 2, '有基礎', '控制下降速度，感受背部收縮', '', '保持身體穩定，避免擺動'),

('俯身槓鈴划船', '中背', 6, 8, 8, 12, 3, 5, 3, 4, 60, 80, 50, 70, '俯身約45度，握住槓鈴，從膝蓋高度拉至腹部，然後緩慢下降', '俯身划船是練中背的主要動作', 3, '進階', '保持背部挺直，避免圓背', '', '感受中背的收縮，控制重量'),

('窄握纜繩下拉', '上背', 8, 12, 10, 15, 3, 4, 3, 4, 50, 70, 40, 60, '坐在下拉機前，窄握把手，從頭頂上方拉至胸部，然後緩慢上升', '窄握下拉主要訓練上背肌', 2, '有基礎', '控制下降速度，感受背部收縮', '', '保持胸部挺起，避免擺動'),

('纜繩面拉', '肩膀後束', 10, 15, 12, 20, 2, 4, 3, 4, 25, 40, 20, 35, '站在纜繩機前，握住繩索，從前方拉至面部，感受肩膀後束收縮', '纜繩面拉主要訓練肩膀後束', 2, '有基礎', '保持肘部高度，避免過度外展', '', '感受肩膀後束的收縮，控制重量'),

('槓鈴彎舉', '二頭肌', 8, 12, 10, 15, 3, 4, 3, 4, 30, 45, 25, 40, '站立，雙手握住槓鈴，從手臂伸直位置彎舉至肩膀，然後緩慢下降', '槓鈴彎舉是練二頭肌的經典動作', 1, '新手', '保持肘部固定，避免擺動', '', '感受二頭肌的收縮，控制重量'),

('纜繩垂式彎舉', '二頭肌', 10, 15, 12, 20, 2, 4, 3, 4, 25, 40, 20, 35, '站在纜繩機前，握住繩索，從手臂伸直位置彎舉至肩膀，保持垂式握法', '垂式彎舉主要訓練二頭肌外側', 2, '有基礎', '保持垂式握法，感受二頭肌收縮', '', '控制重量，避免借力');

