INSERT IGNORE INTO exercises (name, target_muscle, hypertrophy_reps_min, hypertrophy_reps_max, fatloss_reps_min, fatloss_reps_max, hypertrophy_sets_min, hypertrophy_sets_max, fatloss_sets_min, fatloss_sets_max, hypertrophy_load_min_pct, hypertrophy_load_max_pct, fatloss_load_min_pct, fatloss_load_max_pct, instruction_full, instruction_short, difficulty, user_level, notes, video_url, instruction_cues) VALUES
('深蹲', '股四頭肌', 6, 8, 8, 12, 3, 5, 3, 4, 100, 120, 80, 100, '雙腳與肩同寬，背部挺直，從站立位置下降至大腿平行地面，然後站起', '深蹲是練腿的基礎動作', 2, '有基礎', '保持背部挺直，膝蓋不要內扣', '', '控制下降速度，感受股四頭肌收縮'),

('羅馬尼亞硬舉', '股二頭肌', 8, 12, 10, 15, 3, 4, 3, 4, 80, 100, 60, 80, '站立，握住槓鈴，從站立位置下降至膝蓋後方，感受股二頭肌拉伸，然後站起', '羅馬尼亞硬舉主要訓練股二頭肌', 3, '進階', '保持背部挺直，感受股二頭肌拉伸', '', '控制下降速度，避免圓背'),

('史密斯臀推', '臀肌', 6, 8, 8, 12, 3, 4, 3, 4, 60, 80, 50, 70, '坐在史密斯機前，背部靠在墊子上，從坐姿位置推起至臀部收縮，然後下降', '史密斯臀推主要訓練臀肌', 2, '有基礎', '感受臀肌收縮，控制重量', '', '保持核心穩定，避免腰部過度彎曲'),

('俯身腿彎舉', '股二頭肌', 8, 12, 10, 15, 3, 4, 3, 4, 40, 60, 30, 50, '俯臥在腿彎舉機上，從腿部伸直位置彎舉至腳跟接近臀部，然後緩慢下降', '俯身腿彎舉主要訓練股二頭肌', 1, '新手', '控制重量，感受股二頭肌收縮', '', '避免擺動，保持穩定'),

('坐姿腿屈伸', '股四頭肌', 10, 15, 12, 20, 3, 4, 3, 4, 40, 60, 30, 50, '坐在腿屈伸機上，從腿部彎曲位置伸直至膝蓋鎖定，然後緩慢下降', '坐姿腿屈伸主要訓練股四頭肌', 1, '新手', '控制重量，感受股四頭肌收縮', '', '避免擺動，保持穩定'),

('負重提踵', '小腿', 10, 15, 12, 20, 3, 4, 3, 4, 50, 70, 40, 60, '站立，肩部負重，從腳跟下降位置提踵至腳尖，然後緩慢下降', '負重提踵主要訓練小腿肌', 1, '新手', '感受小腿收縮，控制重量', '', '保持平衡，避免擺動');
